import{_ as e,o,c as a,a1 as r}from"./chunks/framework.DYnGRJP5.js";const p=JSON.parse('{"title":"Typography & Colors","description":"","frontmatter":{},"headers":[],"relativePath":"2ndbrain/design/typography-and-colors.md","filePath":"2ndbrain/design/typography-and-colors.md"}'),d={name:"2ndbrain/design/typography-and-colors.md"};function n(i,t,s,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="typography-colors" tabindex="-1">Typography &amp; Colors <a class="header-anchor" href="#typography-colors" aria-label="Permalink to &quot;Typography &amp; Colors&quot;">​</a></h1><p>The design language of 2ndBrain avoids typical flat SaaS design in favor of a cinematic, high-fidelity dark aesthetic.</p><h2 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h2><p>Three distinct font stacks are used:</p><ol><li><strong>Inter (<code>--font-sans</code>)</strong><ul><li><strong>Usage</strong>: The primary body font used inside the BlockNote editor and system UI.</li><li><strong>Why</strong>: Maximum legibility, excellent x-height for long-form reading.</li></ul></li><li><strong>Playfair Display (<code>--font-serif</code>)</strong><ul><li><strong>Usage</strong>: Hero headlines, landing page section titles, and the XP level indicator.</li><li><strong>Why</strong>: Brings a touch of editorial elegance that contrasts sharply with the cyber-aesthetic.</li></ul></li><li><strong>Courier New (<code>--font-mono</code>)</strong><ul><li><strong>Usage</strong>: Status indicators, terminal boot sequences, and scrolling tickers.</li><li><strong>Why</strong>: Reinforces the &quot;system terminal&quot; <code>.exe</code> motif.</li></ul></li></ol><h2 id="core-color-palette" tabindex="-1">Core Color Palette <a class="header-anchor" href="#core-color-palette" aria-label="Permalink to &quot;Core Color Palette&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Usage</th></tr></thead><tbody><tr><td><code>--accent</code></td><td><code>#cfa861</code></td><td>Primary gold accent. Used for buttons, active link indicators, and the XP bar glow.</td></tr><tr><td><code>--bg-main</code></td><td><code>#020203</code></td><td>The absolute lowest z-index background (near black).</td></tr><tr><td><code>--bg-panel</code></td><td><code>#050508</code></td><td>Slightly elevated background for the left sidebar and right right info panels.</td></tr><tr><td><code>--text-muted</code></td><td><code>#888888</code></td><td>Used for subtext, descriptions, and inactive node labels in the graph.</td></tr><tr><td><code>--success</code></td><td><code>#4ade80</code></td><td>Used exclusively to indicate a successful &quot;Synced&quot; state to the cloud.</td></tr><tr><td><code>--danger</code></td><td><code>#ef4444</code></td><td>Used for destructive confirmation modals and error states.</td></tr></tbody></table>',7)])])}const y=e(d,[["render",n]]);export{p as __pageData,y as default};
